package id.intentgate.basicauth

import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith

/** Cross-language test vectors generated by the TypeScript reference (spec/test-vectors.json). */
class VectorsTest {
    @Suppress("UNCHECKED_CAST")
    private val vectors = Json.parse(File(System.getProperty("testVectors")).readText(Charsets.UTF_8)) as Map<String, Any?>

    @Test
    fun jcsMatchesReference() {
        for (case in vectors["jcs"] as List<*>) {
            case as Map<*, *>
            assertEquals(case["canonical"], Jcs.canonicalize(case["input"]))
        }
    }

    @Test
    fun challengeMatchesReference() {
        val v = vectors["challenge"] as Map<*, *>
        @Suppress("UNCHECKED_CAST")
        val event = CheckInEvent.fromJsonMap(v["event"] as Map<String, Any?>)
        assertEquals(v["event_canonical"], event.canonicalJson())
        assertEquals(v["challenge_b64url"], Challenge.computeBase64Url(event))
    }

    @Test
    fun rejectsWhatTheReferenceRejects() {
        assertFailsWith<Jcs.CanonicalizationException> { Jcs.canonicalize(mapOf("a" to 1.5)) }
        assertFailsWith<Jcs.CanonicalizationException> { Jcs.canonicalize(9_007_199_254_740_992L) }
        assertEquals("\"\\ud800\"", Jcs.canonicalize("\ud800"))
    }
}
